-- compatibility: breaking
-- Pending manual evidence participates in close; old runtimes must not ignore it.
CREATE TABLE manual_review_withdrawals(request_id TEXT PRIMARY KEY REFERENCES manual_review_requests(id),book_id TEXT NOT NULL REFERENCES books(id),request_version INTEGER NOT NULL CHECK(request_version>0),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),withdrawn_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TRIGGER rr_manual_withdrawal_insert BEFORE INSERT ON manual_review_withdrawals BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM manual_review_requests r JOIN books b ON b.id=r.book_id JOIN service_book_user_permissions p ON p.book_id=b.id AND p.user_id=accounting_actor_user() AND p.can_edit WHERE r.id=NEW.request_id AND r.book_id=NEW.book_id AND r.version=NEW.request_version AND r.status='pending' AND r.prepared_by=accounting_actor_user() AND NEW.withdrawn_by=accounting_actor_user() AND b.firm_id=accounting_actor_firm() AND EXISTS(SELECT 1 FROM periods pr WHERE pr.book_id=b.id AND pr.status='open') AND NOT EXISTS(SELECT 1 FROM internal_period_locks lk WHERE lk.book_id=b.id)) THEN RAISE(ABORT,'Only current preparer may withdraw pending manual request') END;
END;
CREATE TRIGGER rr_manual_withdrawal_update BEFORE UPDATE ON manual_review_withdrawals BEGIN SELECT RAISE(ABORT,'Manual withdrawal immutable'); END;
CREATE TRIGGER rr_manual_withdrawal_delete BEFORE DELETE ON manual_review_withdrawals BEGIN SELECT RAISE(ABORT,'Manual withdrawal immutable'); END;
CREATE TRIGGER rr_manual_not_withdrawn BEFORE UPDATE ON manual_review_requests WHEN NEW.status='approved' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM manual_review_withdrawals WHERE request_id=NEW.id) THEN RAISE(ABORT,'Withdrawn manual request cannot be reviewed') END;
END;
CREATE TRIGGER rr_manual_withdrawal_revision AFTER INSERT ON manual_review_withdrawals BEGIN
 INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER rr_manual_pending_revision_insert AFTER INSERT ON manual_review_requests BEGIN
 INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER rr_manual_pending_revision_update AFTER UPDATE ON manual_review_requests BEGIN
 INSERT INTO close_dependency_revisions(scope_kind,scope_id,revision) VALUES('book',NEW.book_id,1) ON CONFLICT(scope_kind,scope_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER rr_manual_close_periods_insert BEFORE INSERT ON periods WHEN NEW.status='closed' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM manual_review_requests r WHERE r.book_id=NEW.book_id AND NOT EXISTS(SELECT 1 FROM manual_review_withdrawals w WHERE w.request_id=r.id) AND NOT EXISTS(SELECT 1 FROM vouchers v JOIN voucher_review_completions c ON c.id=v.id WHERE v.review_request_id=r.id)) THEN RAISE(ABORT,'Outstanding manual reviews must be posted or withdrawn before closing') END; END;
CREATE TRIGGER rr_manual_close_periods_update BEFORE UPDATE ON periods WHEN NEW.status='closed' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM manual_review_requests r WHERE r.book_id=NEW.book_id AND NOT EXISTS(SELECT 1 FROM manual_review_withdrawals w WHERE w.request_id=r.id) AND NOT EXISTS(SELECT 1 FROM vouchers v JOIN voucher_review_completions c ON c.id=v.id WHERE v.review_request_id=r.id)) THEN RAISE(ABORT,'Outstanding manual reviews must be posted or withdrawn before closing') END; END;
CREATE TRIGGER rr_manual_close_internal_period_locks_insert BEFORE INSERT ON internal_period_locks BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM manual_review_requests r WHERE r.book_id=NEW.book_id AND NOT EXISTS(SELECT 1 FROM manual_review_withdrawals w WHERE w.request_id=r.id) AND NOT EXISTS(SELECT 1 FROM vouchers v JOIN voucher_review_completions c ON c.id=v.id WHERE v.review_request_id=r.id)) THEN RAISE(ABORT,'Outstanding manual reviews must be posted or withdrawn before closing') END; END;
CREATE VIEW closing_fact_basis_pre_review_policy AS SELECT b.id AS book_id,json_patch(v.inputs_json,json_object('service_plan_versions',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'version',t.version,'lead_user_id',t.lead_user_id,'reviewer_user_id',t.reviewer_user_id,'backup_user_id',t.backup_user_id,'contact_user_id',t.contact_user_id,'due_on',t.due_on,'notes',t.notes,'reason',t.reason,'updated_by',t.updated_by,'updated_at',t.updated_at) AS record FROM service_plan_versions t WHERE t.book_id=b.id ORDER BY t.version))),'material_requests',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'period',t.period,'template_id',t.template_id,'item_key',t.item_key,'title',t.title,'description',t.description,'required',t.required,'due_on',t.due_on,'assignee_user_id',t.assignee_user_id,'created_by',t.created_by,'created_at',t.created_at) AS record FROM material_requests t WHERE t.book_id=b.id ORDER BY t.id))),'material_request_actions',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'request_id',t.request_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'version',t.version,'action',t.action,'state',t.state,'mode',t.mode,'reason',t.reason,'event_ids_json',t.event_ids_json,'evidence_json',t.evidence_json,'attachment_ids_json',t.attachment_ids_json,'attachment_evidence_json',t.attachment_evidence_json,'created_by',t.created_by,'created_at',t.created_at) AS record FROM material_request_actions t WHERE t.book_id=b.id ORDER BY t.id))),'material_attachments',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'request_id',t.request_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'storage_key',t.storage_key,'filename',t.filename,'media_type',t.media_type,'sha256',t.sha256,'size_bytes',t.size_bytes,'created_by',t.created_by,'created_at',t.created_at) AS record FROM material_attachments t WHERE t.book_id=b.id ORDER BY t.id))))) AS inputs_json FROM books b JOIN closing_fact_basis_stage24 v ON v.book_id=b.id;
DROP VIEW closing_fact_basis;
CREATE VIEW closing_issue_rows_pre_review_policy AS SELECT * FROM closing_issue_rows_stage24
 UNION ALL SELECT r.book_id,'required_material','material_request',r.id,'本月必交资料尚未独立验收，或已验收证据发生变化，请核对资料清单'
 FROM material_requests r JOIN service_material_currentness c ON c.request_id=r.id WHERE r.required=1 AND c.is_current=0;
DROP VIEW closing_issue_rows;
CREATE VIEW closing_fact_basis AS SELECT b.id AS book_id,json_patch(v.inputs_json,json_object('manual_review_requests',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'book_id',t.book_id,'version',t.version,'prepared_by',t.prepared_by,'status',t.status,'policy_version',t.policy_version,'content_json',t.content_json,'content_fingerprint',t.content_fingerprint,'command_key',t.command_key,'reason',t.reason,'reviewed_by',t.reviewed_by,'reviewed_at',t.reviewed_at,'independent',t.independent,'review_reason',t.review_reason,'created_at',t.created_at) AS record FROM manual_review_requests t WHERE t.book_id=b.id ORDER BY t.id))),'manual_review_withdrawals',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM(SELECT json_object('request_id',t.request_id,'book_id',t.book_id,'request_version',t.request_version,'reason',t.reason,'withdrawn_by',t.withdrawn_by,'created_at',t.created_at) AS record FROM manual_review_withdrawals t WHERE t.book_id=b.id ORDER BY t.request_id))),'manual_posted_vouchers',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'book_id',t.book_id,'review_request_id',t.review_request_id,'review_mode',t.review_mode,'review_maker_id',t.review_maker_id,'review_reviewer_id',t.review_reviewer_id,'voucher_review_policy_version',t.voucher_review_policy_version,'review_completion_id',t.review_completion_id) AS record FROM vouchers t WHERE t.book_id=b.id AND t.review_request_id IS NOT NULL ORDER BY t.id))))) AS inputs_json FROM books b JOIN closing_fact_basis_pre_review_policy v ON v.book_id=b.id;
CREATE VIEW closing_issue_rows AS SELECT * FROM closing_issue_rows_pre_review_policy UNION ALL SELECT r.book_id,'manual_review_pending','manual_review_request',r.id,'手工凭证尚未完成审核与正式记账；未审核申请可由制单人明确撤回' FROM manual_review_requests r WHERE NOT EXISTS(SELECT 1 FROM manual_review_withdrawals w WHERE w.request_id=r.id) AND NOT EXISTS(SELECT 1 FROM vouchers v JOIN voucher_review_completions c ON c.id=v.id WHERE v.review_request_id=r.id);
